import{_ as s}from"./chunks/npu_3510_hw_arch_sync.DHjro_LS.js";import{_ as c}from"./chunks/atlas_a2_a3_architecture.QjujfbJW.js";import{_ as a,a as _}from"./chunks/intra_core_parallel_pipeline_execution_timing.BdSPSiwi.js";import{_ as d,o as e,a as n,b as o}from"./app.UgfkfLuP.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"核内同步","link":"/api/SIMD-API/c_api/sync/intra_core_sync/intra_core_sync"},{"text":"核内同步能力概述","link":"/api/SIMD-API/c_api/sync/intra_core_sync/intra_core_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/intra_core_sync/intra_core_sync_overview.md","filePath":"api/SIMD-API/c_api/sync/intra_core_sync/intra_core_sync_overview.md","outlineHeaders":[{"level":2,"title":"为什么需要核内同步","slug":"为什么需要核内同步","link":"#为什么需要核内同步"},{"level":2,"title":"硬件流水类型","slug":"硬件流水类型","link":"#硬件流水类型"},{"level":2,"title":"核内同步分类","slug":"核内同步分类","link":"#核内同步分类"},{"level":2,"title":"什么时候需要开发者手动插入同步","slug":"什么时候需要开发者手动插入同步","link":"#什么时候需要开发者手动插入同步"}],"lastUpdated":1793082324000}'),E={name:"api/SIMD-API/c_api/sync/intra_core_sync/intra_core_sync_overview.md"};function P(p,t,r,I,i,l){return e(),n("div",null,[...t[0]||(t[0]=[o('<div><article class="markdown-body"><h1>核内同步能力概述</h1><h2 id="为什么需要核内同步">为什么需要核内同步<a class="header-anchor" href="#为什么需要核内同步">​</a></h2><p>AI Core内部的执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行的方式运行，在读写同一存储资源时可能存在数据依赖关系。为确保数据一致性及计算正确性，需通过同步控制协调操作时序。</p><div data-filter="950"><p>针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构3510</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图1</strong> NPU架构3510架构图<br><img src="'+s+'" alt></p></div><div data-filter="A3,910b"><p>针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构2201</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图2</strong> NPU架构2201架构图<br><img src="'+c+'" alt></p></div><p>下图示例描述了一个常见的Vector计算数据流：</p><ol><li>先通过DMA执行单元将数据从GM搬入到Local Memory；</li><li>进行计算；</li><li>然后再通过DMA执行单元将计算结果从Local Memory搬出到GM。</li></ol><p><strong>图3</strong> Vector计算数据流示意图<br><img src="'+a+'" alt></p><p>四个执行单元Scalar、Vector、DMA（MTE2）、DMA（MTE3）并行执行，若访问同一片Local Memory，需要同步机制来控制它们的访问时序：保证先搬入Local Memory后再计算，计算完成后再搬出。</p><p><strong>图4</strong> 核内并行流水执行时序示意图<br><img src="'+_+`" alt></p><h2 id="硬件流水类型">硬件流水类型<a class="header-anchor" href="#硬件流水类型">​</a></h2><p>AI Core内部并行的指令流水类型和解释如下所示：</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>不同的硬件架构，每一种硬件流水类型包含的具体流水会有所差异，详细介绍请参考<a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/hardware_implementation.html">硬件实现</a>章节。</p></div><p><strong>表1</strong> 指令流水类型和相关说明</p><table><thead><tr><th>流水类型</th><th>含义</th></tr></thead><tbody><tr><td>PIPE_S</td><td>标量流水，使用标量访存语句或标量计算接口访问GM、片上存储地址时为此流水</td></tr><tr><td>PIPE_V</td><td>矢量计算流水及部分硬件架构下的L0C Buffer-&gt;UB数据搬运流水</td></tr><tr><td>PIPE_M</td><td>矩阵计算流水</td></tr><tr><td>PIPE_MTE1</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer数据搬运流水</td></tr><tr><td>PIPE_MTE2</td><td>GM-&gt;L1 Buffer、GM-&gt;UB等数据搬运流水</td></tr><tr><td>PIPE_MTE3</td><td>UB-&gt;GM等数据搬运流水</td></tr><tr><td>PIPE_FIX</td><td>L0C Buffer-&gt;GM、L0C Buffer-&gt;L1 Buffer等数据搬运流水</td></tr></tbody></table><p>此外，<code>PIPE_ALL</code>表示全部流水，用于需要等待所有流水前序指令完成的场景。</p><p>同步接口中<code>pipe_t</code>枚举类型的取值如下：<a id="硬件流水类型"></a></p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">typedef</span><span class="w"> </span><span class="k">enum</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">PIPE_S</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_V</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_M</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_MTE1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_MTE2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_MTE3</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_ALL</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="p">,</span>
<span class="w">    </span><span class="n">PIPE_FIX</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">10</span>
<span class="p">}</span><span class="w"> </span><span class="n">pipe_t</span><span class="p">;</span>
</code></pre></div><h2 id="核内同步分类">核内同步分类<a class="header-anchor" href="#核内同步分类">​</a></h2><p>对上述核内并行流水的同步控制可按表2选择。</p><p><strong>表2</strong> 核内同步接口分类说明</p><table><thead><tr><th>同步类型</th><th>接口</th><th>适用场景</th><th>差异点</th></tr></thead><tbody><tr><td>多流水同步</td><td><a href="asc_sync_notify.html">asc_sync_notify</a>/<a href="asc_sync_wait.html">asc_sync_wait</a></td><td>同一核内具有数据依赖的不同类型流水指令之间的同步。</td><td>需要开发者显式指定一对源流水和目的流水。<code>asc_sync_notify</code>在源流水前序指令的所有读写操作完成后设置标志位；<code>asc_sync_wait</code>阻塞目的流水，直至检测到该标志位，解除阻塞并清除标志位。</td></tr><tr><td>多流水同步</td><td><a href="asc_lock.html">asc_lock</a>/<a href="asc_unlock.html">asc_unlock</a></td><td>同一核内不同流水之间的同步控制。</td><td>通过<code>mutex_id</code>锁定和释放指定流水。<code>asc_lock</code>根据<code>mutex_id</code>获取Mutex，若Mutex已被锁定，将阻塞指定流水上后续指令的执行；<code>asc_unlock</code>在指定流水的前序指令执行完成后释放对应Mutex。与<code>asc_sync_notify</code>/<code>asc_sync_wait</code>相比，该组合内聚性更强、与其他流水解耦，可简化反向同步逻辑。</td></tr><tr><td>多流水同步</td><td><a href="asc_sync_mte2.html">asc_sync_mte2</a>、<a href="asc_sync_mte3.html">asc_sync_mte3</a>、<a href="asc_sync_vec.html">asc_sync_vec</a></td><td>需要同时阻塞多条目的流水，直到指定源流水的前序指令完成。</td><td><strong>易用性接口</strong>，内部封装了多对<code>asc_sync_notify</code>与<code>asc_sync_wait</code>。<br><code>asc_sync_mte2</code>等价于分别执行<code>PIPE_MTE2</code>-&gt;<code>PIPE_MTE3</code>和<code>PIPE_MTE2</code>-&gt;<code>PIPE_V</code>两组同步。<br><code>asc_sync_mte3</code>等价于分别执行<code>PIPE_MTE3</code>-&gt;<code>PIPE_MTE2</code>和<code>PIPE_MTE3</code>-&gt;<code>PIPE_V</code>两组同步。<br><code>asc_sync_vec</code>等价于分别执行<code>PIPE_V</code>-&gt;<code>PIPE_MTE2</code>、<code>PIPE_V</code>-&gt;<code>PIPE_MTE3</code>和<code>PIPE_V</code>-&gt;<code>PIPE_S</code>三组同步。</td></tr><tr><td>单流水同步</td><td><a href="asc_sync_pipe.html">asc_sync_pipe</a></td><td>同一核内具有数据依赖的相同类型流水指令之间的同步。</td><td>同一流水中虽然指令是顺序执行，但后一条指令开始执行时前一条指令不一定执行结束。<code>asc_sync_pipe</code>保证前序指令中所有数据读写全部完成后，后序指令才开始执行。该接口不支持<code>PIPE_S</code>单流水同步。</td></tr><tr><td>全流水同步</td><td><a href="asc_sync.html">asc_sync</a></td><td>需要阻塞调用点后所有硬件流水的后序指令，直到调用点之前所有硬件流水的前序指令全部完成。</td><td>功能与<code>asc_sync_pipe(PIPE_ALL)</code>等价，适用于无法只约束单条流水的场景。</td></tr><tr><td>内存访问屏障</td><td><a href="asc_sync_data_barrier.html">asc_sync_data_barrier</a></td><td>需要等待此前已发出但尚未完成的内存访问指令全部执行完成。</td><td>通过<code>arg</code>参数指定屏障作用的内存范围，确保屏障前后的内存访问指令按预期顺序完成。</td></tr></tbody></table><div data-filter="A3,910b"><p>以<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构2201</a>为例，该硬件架构下所有合法的核内同步组合如<a href="#aic_intra_core_sync_combinations">表3</a>和<a href="#aiv_intra_core_sync_combinations">表4</a>所示。其中，“不涉及”表示硬件层面不存在此种同步组合，“暂无应用场景”表示存在此种同步组合，但在实际开发场景中暂不需要使用。</p><p><a id="aic_intra_core_sync_combinations"></a></p><p><strong>表3</strong> AIC中所有合法的核内同步组合</p><table><thead><tr><th>源流水/目的流水</th><th>PIPE_S</th><th>PIPE_M</th><th>PIPE_MTE1</th><th>PIPE_MTE2</th><th>PIPE_MTE3</th><th>PIPE_FIX</th></tr></thead><tbody><tr><td>PIPE_S</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td></tr><tr><td>PIPE_M</td><td>不涉及</td><td><code>asc_sync_pipe(PIPE_M)</code></td><td><code>asc_sync_notify(PIPE_M, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_M, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_MTE2, EVENT_ID0)</code></td><td>不涉及</td><td><code>asc_sync_notify(PIPE_M, PIPE_FIX, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_M, PIPE_FIX, EVENT_ID0)</code></td></tr><tr><td>PIPE_MTE1</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE1)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_MTE3, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE1, PIPE_FIX, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE1, PIPE_FIX, EVENT_ID0)</code></td></tr><tr><td>PIPE_MTE2</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE2)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code></td><td>暂无应用场景</td></tr><tr><td>PIPE_MTE3</td><td>不涉及</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE1, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE3)</code></td><td>暂无应用场景</td></tr><tr><td>PIPE_FIX</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_FIX, PIPE_M, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_FIX, PIPE_M, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_FIX, PIPE_MTE1, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_FIX, PIPE_MTE1, EVENT_ID0)</code></td><td>暂无应用场景</td><td>暂无应用场景</td><td><code>asc_sync_pipe(PIPE_FIX)</code></td></tr></tbody></table><p><a id="aiv_intra_core_sync_combinations"></a></p><p><strong>表4</strong> AIV中所有合法的核内同步组合</p><table><thead><tr><th>源流水/目的流水</th><th>PIPE_S</th><th>PIPE_V</th><th>PIPE_MTE2</th><th>PIPE_MTE3</th></tr></thead><tbody><tr><td>PIPE_S</td><td>不涉及</td><td><code>asc_sync_notify(PIPE_S, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_S, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_S, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_S, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td>PIPE_V</td><td><code>asc_sync_notify(PIPE_V, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_V)</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_V, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_V, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td>PIPE_MTE2</td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE2)</code></td><td><code>asc_sync_notify(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE2, PIPE_MTE3, EVENT_ID0)</code></td></tr><tr><td>PIPE_MTE3</td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_S, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_S, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_V, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_V, EVENT_ID0)</code></td><td><code>asc_sync_notify(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code><br><code>asc_sync_wait(PIPE_MTE3, PIPE_MTE2, EVENT_ID0)</code></td><td><code>asc_sync_pipe(PIPE_MTE3)</code></td></tr></tbody></table></div><h2 id="什么时候需要开发者手动插入同步">什么时候需要开发者手动插入同步<a class="header-anchor" href="#什么时候需要开发者手动插入同步">​</a></h2><p>C API编程方式下所有的同步均需开发者手动管理。</p></article></div>`,1)])])}const m=d(E,[["render",P]]);export{f as __pageData,m as default};
